{
  "review_title": "可见光消色差超构透镜的色散约束与效率权衡：物理界限、设计机制与实证表现",
  "central_question": "在可见光消色差超构透镜中，相位与群延迟色散的物理限制如何共同制约带宽与视场的联合性能？现有证据如何支持由此产生的效率权衡？",
  "provisional_scope": "本综述聚焦于可见光波段（~400-700 nm）的消色差超构透镜，严格区分三个层面：(1) 由单界面几何与色散工程原理决定的物理理论界限；(2) 用于缓解色散限制的纳米结构设计机制及其内在权衡；(3) 已制备器件的实验性能数据。范围限定于基于局部相位调控（传播延迟或共振相位）的色散工程策略，明确排除纯衍射能量重分配方案及多元件复合系统的详细分析（仅作为背景提及）。鉴于试点限制，深度分析将集中于两篇核心全文材料，分别提供基础物理界限的理论框架与关键设计/性能评估视角，不强行凑足三篇无关文献。",
  "material_theme_inventory": [
    {
      "theme": "单界面几何对视场与像差的根本限制",
      "evidence_source": "P0001",
      "key_finding": "高数值孔径（NA）下单界面超构透镜的视场受彗差和像散限制极小（如 NA=0.5 时 <5 µm），这是无法通过单层相位分布校正的物理边界。",
      "relevance_to_question": "直接回答 F1，确立 FOV 的物理下限，解释为何宽带宽与大视场难以在单层结构中并存。"
    },
    {
      "theme": "衍射效率的波长依赖性与色散解耦挑战",
      "evidence_source": "P0001",
      "key_finding": "衍射元件效率遵循 sinc² 函数依赖，且焦距与波长的解耦在连续波段极具挑战性；离散波长复用可行但复杂。",
      "relevance_to_question": "支撑 F1 与 F2，说明带宽扩展面临的固有效率损失机制。"
    },
    {
      "theme": "宽视场色散工程的带宽饱和效应",
      "evidence_source": "P0002",
      "key_finding": "量化了带宽随 NA 和 FOV 增加而减小的趋势，并发现高 FOV 下带宽存在饱和现象；最大群延迟需求不一定出现在最大入射角。",
      "relevance_to_question": "核心支撑 F1，提供具体的数学界限公式，修正对“大视场必然导致带宽急剧下降”的简单直觉，指出特定几何配置下的优化空间。"
    },
    {
      "theme": "元原子设计机制与离轴效率损耗",
      "evidence_source": "P0001",
      "key_finding": "波导型与共振型设计的对比；共振结构在斜入射下因反对称局域模式导致效率下降，影响大视场性能。",
      "relevance_to_question": "支撑 F2，揭示设计机制引入的额外效率权衡，特别是针对大视场应用。"
    },
    {
      "theme": "实验性能评估与基准比较的误导性",
      "evidence_source": "P0001",
      "key_finding": "现有高 NA 金属透镜绝对效率虽高（~86%），但 MTF 和旁瓣分析显示其偏离衍射极限；将单元件与多元件商业物镜直接比较是不恰当的。",
      "relevance_to_question": "支撑 F3，提供批判性视角评估实验数据，强调在比较带宽、FOV 和效率时需考虑像差校正水平的差异。"
    }
  ],
  "provisional_outline": {
    "chapters": [
      {
        "chapter_id": "CH1",
        "title": "物理界限：色散与几何约束下的带宽 - 视场积",
        "purpose": "建立可见光消色差超构透镜的理论性能天花板，分离单界面几何像差限制与色散工程本身的带宽限制。",
        "question": "相位与群延迟色散的物理定律如何量化地限制联合带宽与视场？单界面几何是否构成了不可逾越的视场瓶颈？"
      },
      {
        "chapter_id": "CH2",
        "title": "设计机制：色散补偿策略与效率权衡的微观起源",
        "purpose": "分析实现消色差的具体纳米结构设计（波导型 vs 共振型），探讨其为克服物理界限所付出的代价（如耦合损耗、角度敏感性）。",
        "question": "不同的色散工程设计机制如何在拓展带宽和视场的同时，引入新的效率损失机制或制造复杂性？"
      },
      {
        "chapter_id": "CH3",
        "title": "实证表现：已制备器件的性能边界与评估基准",
        "purpose": "综合现有实验数据，评估实际器件距离理论界限的差距，并批判性地分析性能报告中的比较基准问题。",
        "question": "当前实验实现的带宽、视场和效率组合是否触及理论预测的饱和区？现有的性能评估方法是否存在系统性偏差？"
      }
    ]
  },
  "cross_chapter_rules": [
    "严格区分‘理论最大值’（来自 P0002 的公式推导）与‘实际可实现值’（受 P0001 所述材料损耗、模式耦合限制）。",
    "在讨论视场（FOV）时，必须明确区分由‘单界面几何像差’（CH1 重点）导致的限制与由‘色散工程带宽饱和’（CH1/CH2 交叉）导致的限制，避免混淆。",
    "引用实验数据（CH3）时，需同步引用 P0001 中关于比较基准的警告，不得将单元件超构透镜的性能直接与多片式商业镜头对标，除非明确说明像差校正状态的差异。",
    "所有关于‘效率权衡’的论述必须具体到物理机制（如 sinc² 依赖、反对称模式激发），而非泛泛而谈。"
  ],
  "grouped_screening_notes": "候选池共 2 篇全文（P0001, P0002），均高度相关且互补。P0002 提供了核心的带宽 - 视场定量界限，直接回应 R1；P0001 提供了广泛的物理背景、设计机制分类及对实验评估的批判性视角，回应 R2 和 R3。由于试点限制为‘最多 3 篇’，且现有 2 篇已能完整覆盖物理界限、设计机制和实证评估三个维度，无需再检索第三篇全文以避免冗余或引入低相关性材料。未入选原因主要为池内无其他可用全文。",
  "supplement_requests": [],
  "directed_reads": [
    {
      "paper_id": "P0002",
      "chapter_ids": ["CH1"],
      "questions": [
        "文中推导的带宽上限公式在不同 NA 和 FOV 组合下的具体数值表现如何？",
        "‘带宽饱和’现象发生的临界 FOV 条件是什么？其物理根源是孔径截断还是相位梯度需求变化？"
      ],
      "required_outputs": "提取带宽界限公式，整理 NA-FOV-Bandwidth 三维关系的定性描述，记录关于 r0=Ftan(alpha) 与 r0=Fa 两种焦点定义对结果的影响。",
      "knowledge_gap": "需要确认该理论模型是否考虑了矢量衍射效应或仅限于标量近似。",
      "reason": "作为 CH1 的核心定量依据，需精确理解其假设边界以确保综述结论的严谨性。"
    },
    {
      "paper_id": "P0001",
      "chapter_ids": ["CH2", "CH3"],
      "questions": [
        "共振型超构透镜在斜入射下效率下降的具体机制（反对称模式）是否有定量数据支持？",
        "文中提到的‘不恰当比较’具体指哪些案例？是否有重新评估后的性能指标建议？"
      ],
      "required_outputs": "归纳波导型与共振型设计的优缺点对比表，提取关于实验评估标准的批判性论点，记录具体的高 NA 器件效率数据及 MTF 特征。",
      "knowledge_gap": "需明确文中引用的 Kho16 和 Lal99 数据的具体实验条件（波长、NA、测量方法）。",
      "reason": "为 CH2 的设计机制分析和 CH3 的实验评估提供关键的定性框架和警示案例。"
    }
  ]
}

